package com.sakan.iptv;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

public class ViewingOptionsTest {
 @Test public void bufferProfilesRespectEngineConstraintsAndFallback(){for(String id:Arrays.asList("fast","balanced","stable","bad")){BufferProfile b=BufferProfile.of(id);assertTrue(b.maximum>=b.minimum);assertTrue(b.minimum>=b.start);assertTrue(b.minimum>=b.rebuffer);assertTrue(b.start>0);}assertEquals("balanced",BufferProfile.of("bad").id);assertTrue(BufferProfile.of("stable").rebuffer>BufferProfile.of("fast").rebuffer);}
 @Test public void recallIgnoresSameChannelAndAlternatesConfirmedChannels(){ChannelRecall r=new ChannelRecall();r.ready("live:item:1");assertEquals("",r.previous());r.ready("live:item:1");assertEquals("",r.previous());r.ready("live:item:2");assertEquals("live:item:1",r.previous());r.ready(r.previous());assertEquals("live:item:2",r.previous());r.clear();assertEquals("",r.previous());}
 @Test public void customOrderSurvivesProviderAdditionsAndTemporaryRemoval(){CatalogLayout l=new CatalogLayout("{}");List<String> all=Arrays.asList("a","b","c");l.move(false,"c","a",all);assertEquals(Arrays.asList("c","a","b"),l.ordered(false,all));assertEquals(Arrays.asList("c","a","b","d"),l.ordered(false,Arrays.asList("a","b","c","d")));l.move(false,"b","a",Arrays.asList("a","b"));assertEquals(Arrays.asList("b","a","c"),l.ordered(false,all));}
 @Test public void moveDownEndAndAlreadyAtTopRemainPredictable(){CatalogLayout l=new CatalogLayout("{}");List<String> all=Arrays.asList("a","b","c");l.move(false,"a","c",all);assertEquals(Arrays.asList("b","a","c"),l.ordered(false,all));l.move(false,"a",null,all);assertEquals(Arrays.asList("b","c","a"),l.ordered(false,all));l.move(false,"b","b",all);assertEquals(Arrays.asList("b","c","a"),l.ordered(false,all));}
 @Test public void hiddenEntriesPersistAndResetIsScopedToOneList(){CatalogLayout l=new CatalogLayout("{}");l.hide(false,"item:2",true);l.hide(true,"7",true);l.move(false,"item:2","item:1",Arrays.asList("item:1","item:2"));CatalogLayout restored=new CatalogLayout(l.toString());assertTrue(restored.hidden(false,"item:2"));assertTrue(restored.hidden(true,"7"));restored.hide(false,"item:2",false);assertFalse(restored.hidden(false,"item:2"));restored.hide(false,"item:2",true);restored.reset(true);assertFalse(restored.hidden(true,"7"));assertTrue(restored.hidden(false,"item:2"));assertEquals(Arrays.asList("item:2","item:1"),restored.ordered(false,Arrays.asList("item:1","item:2")));}
 @Test public void damagedSettingsAndDuplicateIdsDoNotLoseNewProviderItems(){CatalogLayout damaged=new CatalogLayout("not json");assertEquals(Arrays.asList("a","b"),damaged.ordered(true,Arrays.asList("a","b")));CatalogLayout l=new CatalogLayout("{\"categoryOrder\":[\"b\",\"b\",\"missing\"]}");assertEquals(Arrays.asList("b","a","c"),l.ordered(true,Arrays.asList("a","b","c")));}
}
